    static Station[] byKind;

    /// <summary>The row of a guide kind (0-21), or null.</summary>
    public static Station OfGuideKind(int kind)
    {
        if (byKind == null)
        {
            var map = new Station[32];
            foreach (var s in Stations)
                if (s != null && s.guideKind >= 0 && s.guideKind < map.Length && map[s.guideKind] == null) map[s.guideKind] = s;
            byKind = map;
        }
        return kind >= 0 && kind < byKind.Length ? byKind[kind] : null;
    }

    /// <summary>The row with this code ("2.3"), or null.</summary>
    public static Station Find(string code)
    {
        foreach (var s in Stations) if (s != null && s.code == code) return s;
        return null;
    }

    /// <summary>The first row at a room's slot (1-7; 1 on the hub is 0.1): "1.1" finds 1.1A. Null when none.</summary>
    public static Station At(int room, int slot)
    {
        var key = room + "." + slot;
        foreach (var s in Stations)
            if (s != null && s.code != null && (s.code == key || (s.code.Length == key.Length + 1 && s.code.StartsWith(key, System.StringComparison.Ordinal)))) return s;
        return null;
    }

    /// <summary>The variant letter of a row ("1.1B" -> 'B'), or ' ' for a row with one exhibit.</summary>
    public static char VariantOf(Station s) => s != null && s.code != null && s.code.Length == 4 ? s.code[3] : ' ';

    public static int RoomOf(Station s) => s == null || s.code == null || s.code.Length < 1 ? -1 : s.code[0] - '0';

    public static int SlotOf(Station s) => s == null || s.code == null || s.code.Length < 3 ? 0 : s.code[2] - '0';

    /// <summary>A, B or C for the museum's rule sets; the media bay; a dash.</summary>
    public static string RuleName(Rule r) => r == Rule.Shipped ? "A" : r == Rule.Keys ? "B" : r == Rule.Devices ? "C" : r == Rule.Media ? "MEDIA BAY" : "-";
}
